#!/usr/bin/env node
/**
 * Conventional Commit guard (AGENTS.md "Commit and Release Conventions").
 *
 * Usage:
 *   node scripts/check-commit-message.mjs <rev>...            # e.g. origin/main..HEAD
 *   node scripts/check-commit-message.mjs --message-file <path>
 *
 * Types are the ones this repository uses. AGENTS.md spells feat, fix,
 * refactor, perf, and test with a scope and docs/chore without one, so a scope
 * is required for the code-change types and optional for the rest. Merge
 * commits are skipped: their subject is generated by git or the forge.
 *
 * With no arguments nothing is checked and the script exits 0 — a bare local
 * run has no range to inspect, and the CI job passes the change range in.
 */

import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";

const TYPES = ["feat", "fix", "refactor", "perf", "test", "docs", "chore", "ci", "build", "style", "revert"];
const TYPES_REQUIRING_SCOPE = new Set(["feat", "fix", "refactor", "perf", "test"]);
const HEADER = /^([a-z]+)(?:\(([^)]*)\))?!?: (\S.*)$/;
const SCOPE = /^[a-z0-9][a-z0-9-]*$/;

// Returns a failure reason, or null when the header is acceptable.
function checkHeader(header) {
  // A merge commit's subject is generated by git; ranges are read with
  // --no-merges, so this only matters for --message-file.
  if (header.startsWith("Merge ")) return null;
  const match = HEADER.exec(header);
  if (!match) return 'must look like "type(scope): subject"';
  const [, type, scope] = match;
  if (!TYPES.includes(type)) return `"${type}" is not one of: ${TYPES.join(", ")}`;
  if (scope === undefined && TYPES_REQUIRING_SCOPE.has(type)) {
    return `"${type}" requires a scope, e.g. "${type}(worker): ..."`;
  }
  if (scope !== undefined && !SCOPE.test(scope)) {
    return `scope "${scope}" must be lowercase kebab-case, e.g. "worker" or "e2e"`;
  }
  return null;
}

function messagesFromRevisions(revisions) {
  const result = spawnSync("git", ["log", "--no-merges", "--format=%h%x00%s", ...revisions, "--"], {
    encoding: "utf8",
  });
  if (result.status !== 0) {
    console.error(`git log failed: ${result.stderr.trim() || result.status}`);
    process.exit(1);
  }
  return result.stdout
    .split("\n")
    .filter(Boolean)
    .map((line) => {
      const [revision, subject] = line.split("\0");
      return { revision, subject };
    });
}

function messagesFromFile(path) {
  const header = readFileSync(path, "utf8")
    .split("\n")
    .map((line) => line.trim())
    .find((line) => line !== "" && !line.startsWith("#"));
  return header === undefined ? [] : [{ revision: path, subject: header }];
}

const arguments_ = process.argv.slice(2);
let messages;
if (arguments_.length === 0) {
  console.log("Conventional Commit guard skipped: pass a revision range or --message-file to check.");
  process.exit(0);
} else if (arguments_[0] === "--message-file") {
  messages = messagesFromFile(arguments_[1]);
} else {
  messages = messagesFromRevisions(arguments_);
}

const failures = messages
  .map(({ revision, subject }) => ({ revision, subject, reason: checkHeader(subject) }))
  .filter(({ reason }) => reason !== null);

if (failures.length > 0) {
  console.error("Conventional Commit guard failed:\n");
  for (const { revision, subject, reason } of failures) {
    console.error(`  - ${revision}: ${JSON.stringify(subject)}\n      ${reason}`);
  }
  console.error(`\n${failures.length} commit(s) with a non-conventional subject.`);
  process.exit(1);
}

console.log(`Conventional Commit guard passed (${messages.length} commit message(s)).`);
